import React from 'react';
import { AreaChart as RechartsAreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, Legend, Label } from 'recharts';
import ChartBase from './ChartBase';
import { 
  transformChartData, 
  getDataKeys, 
  getChartColors, 
  limitDataPoints,
  toTitleCase, 
  CHART_THEME, 
  CustomTooltip 
} from './chartUtils';

const AreaChart = ({ chartData, height = 500, maxDataPoints = 50 }) => {
  // Transform and prepare data
  const transformedData = transformChartData(chartData.data);
  const limitedData = limitDataPoints(transformedData, maxDataPoints);
  const dataKeys = getDataKeys(limitedData);
  const colors = getChartColors(dataKeys.length);
  
  // Chart configuration
  const margin = { top: 30, right: 40, left: 80, bottom: 100 };
  
  return (
    <ChartBase 
      title={chartData.title} 
      height={height}
      dataCount={limitedData.length}
      chartType="area"
    >
      <RechartsAreaChart 
        data={limitedData} 
        margin={margin}
      >
        <CartesianGrid {...CHART_THEME.grid} />
        
        <XAxis 
          dataKey="category"
          {...CHART_THEME.axis}
          angle={-45}
          textAnchor="end"
          height={100}
        >
          <Label 
            value="Category" 
            offset={-5} 
            position="insideBottom"
            {...CHART_THEME.label}
          />
        </XAxis>
        
        <YAxis {...CHART_THEME.axis}>
          <Label 
            value={toTitleCase(dataKeys[0] || 'Value')} 
            angle={-90} 
            position="insideLeft"
            {...CHART_THEME.label}
          />
        </YAxis>
        
        <Tooltip 
          content={<CustomTooltip />}
        />
        
        <Legend {...CHART_THEME.legend} />
        
        {dataKeys.map((key, index) => (
          <Area
            key={key}
            type="monotone"
            dataKey={key}
            stroke={colors[index]}
            fill={colors[index]}
            strokeWidth={3}
            fillOpacity={0.3}
            dot={{ 
              fill: colors[index], 
              strokeWidth: 2, 
              r: 4,
              filter: `drop-shadow(0 0 4px ${colors[index]}50)`
            }}
            activeDot={{ 
              r: 6, 
              stroke: colors[index], 
              strokeWidth: 2, 
              fill: colors[index],
              filter: `drop-shadow(0 0 6px ${colors[index]}80)`
            }}
            name={toTitleCase(key)}
          />
        ))}
      </RechartsAreaChart>
    </ChartBase>
  );
};

export default AreaChart;
